"""Documentation only. Read application/reference evidence and prepare the requirement matrix."""
from pathlib import Path
import json, hashlib

OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[1]
rows=[]
def add(level,category,name,purpose,fmt,sample,owner,remark):
    rows.append({'level':level,'category':category,'name':name,'purpose':purpose,'format':fmt,'sample':sample,'owner':owner,'actual':None,'remark':remark})
M='Mandatory'; C='Conditional'; O='Optional'
cat='A. Approval, template and installed equipment libraries'
add(M,cat,'Target SynerGEE product / version','Confirm the receiving installation can interpret the schema and equipment references. SAI_Control.Product must match the approved template.','Exact product/version text; template registry value','Reference: SynerGEE Electric 5.0.0.324','System Planning / SynerGEE Administrator','Mandatory full mode. Reference version is known; actual receiving version needs confirmation. [EPB, WR]')
add(M,cat,'Clean approved MDB template','Provide a genuine empty network template with the approved fields, indexes and relationships, then register and approve it.','Jet MDB file; template code/version; approved registry selection','Reference structure: 50 tables, 1,065 fields, 133 indexes, 41 relationships','SynerGEE Administrator / Application Admin','Mandatory. Schema is available; an approved clean template and review are still required. Hash is generated by the application. [EC, WR]')
add(M,cat,'Installed conductor library revision','Identify the exact external library revision that resolves the conductor IDs used in the exported network.','Versioned library name/revision or controlled release identifier','Not embedded in reference MDBs','Distribution Design / SynerGEE Library Custodian','Mandatory approval input. An equipment ID list is not the actual conductor library. [EC, NV]')
add(M,cat,'Installed transformer library revision','Identify the exact external transformer library containing the approved winding, impedance and loss definitions.','Versioned library name/revision or controlled release identifier','Not embedded in reference MDBs','Transformer Engineering / Library Custodian','Mandatory approval input. Transformer make or kVA label does not identify a library revision. [EC, NV]')
add(M,cat,'Approved conductor model inventory','Provide the installed electrical definitions and literal IDs for every material/size used on an active R/Y/B/N position.','Reviewed library package plus exact ID list; native library units declared','Observed IDs: ANT, DOG, GNAT, WASP, INSULATED ANT; leading-space variants','Distribution Design / Library Custodian','Mandatory for conductors actually used. R/X, ratings and other model data come from the library; GPX/PDF codes do not provide them. [MDB, NV]')
add(M,cat,'Approved transformer model inventory','Provide installed models whose winding ratings and electrical characteristics are confirmed for the surveyed transformers.','Reviewed transformer library package and exact type IDs','Observed labels: 50 KVA, 100 KVA, 200 KVA','Transformer Engineering / Library Custodian','Mandatory for selected types. References contain names, not the model definitions or physical specifications. [MDB, EC]')
add(M,cat,'Approved line-construction model inventory','Confirm the configuration library definition is installed and suitable for the actual construction, not only that its name exists.','Exact configuration IDs and reviewed library definitions','Reference ID: 12.5/7.2 kV cross arm C2-2','Distribution Design / Library Custodian','Mandatory. The voltage-looking part of an ID is not proof of the actual supply voltage. [MDB, EC, EPB]')
add(M,cat,'Current-project engineering approval and design basis','Confirm which historical reference conventions apply to this project and approve the completed engineering configuration.','Controlled design/review reference and authorized approval; app records user/date','Source models include historical MEPCO networks; no HAZECO engineering approval inferred','Chief Engineer / System Planning / Authorized Admin','Mandatory full mode. Do not manually fabricate approval IDs or dates; use the existing approval workflow. [EC, NV]')

cat='B. Coordinate reference system and supply voltages'
add(M,cat,'Projected CRS and zone confirmation','Select the metre-based projected CRS for the actual survey and resolve the reference-label versus coordinate discrepancy.','Projected EPSG integer; units metres; verified GPX/control-point comparison','MDB label implies EPSG:32643; GPX 591 matches EPSG:32642 within 0.46 m','GIS / Survey Department / System Planning','Mandatory unresolved conflict. The same point differs by about 577 km under zone 43N. Do not copy the label without GIS confirmation. [GEO, EC]')
add(M,cat,'CRS name matching the approved EPSG','Supply the projection name written to SAI_Control.ProjectionFile, consistent with the chosen coordinates and EPSG.','Text, maximum 255 characters in the form','Reference: WGS 1984 UTM Zone 43N; label alone is not validated','GIS / Survey Department','Mandatory form field. Current-project EPSG and name must agree; see CRS conflict. [EC, MDB, GEO]')
add(M,cat,'Operating frequency','Confirm the current-project operating frequency used by the receiving electrical models and libraries.','Numeric Hz; form accepts 50 or 60','All nine reference control rows: 60 Hz','System Operations / System Planning','Mandatory. Recorded 60 Hz is source evidence, not approval for this project. [EC, MDB]')
add(M,cat,'Primary supply nominal voltage, line-to-line','Set the feeder nominal voltage in InstFeeders.NominalKvll and keep it consistent with the transformer supply model.','Positive numeric kV line-to-line; form maximum 1,000 kV','Reference: 11 kV; BusVoltageLevel separately 11.37','System Planning / Grid or Distribution Operations','Mandatory. Do not use the separate bus operating voltage as nominal voltage without approval. [EC, EPB, MDB]')
add(M,cat,'LT secondary voltage, line-to-line','Provide actual LT nominal voltage. The form writes this value into InstPrimaryTransformers.SpecNomKv.','Positive numeric kV line-to-line; consistent with NomKvMode and library','Actual LT voltage unresolved. Reference stores SpecNomKv=4.16 with NomKvMode=C','Transformer Engineering / Distribution Planning','Mandatory unresolved input. Previous 0.4kV Data Entry export convention is not an approval for the final SynerGEE model. [EC, MDB]')

cat='C. Line construction and equipment selection'
add(M,cat,'Selected line configuration library ID','Select an installed, approved construction ID for the sections; the module applies its central selection to the model.','Exact case/space-sensitive reviewed ID; form maximum 200 characters','Reference: 12.5/7.2 kV cross arm C2-2','Distribution Design / Library Custodian','Mandatory selection; physical applicability still requires approval. Must exist in approved template references. [EC, EPB]')
add(M,cat,'Phase-to-phase spacing and source-unit interpretation','Confirm actual phase spacing and the meaning of the source MUL number before it is stored in the form field labelled cm.','Positive numeric centimetres in this form; source unit interpretation confirmed','Reference raw PhaseToPhaseSpacing_MUL=121.9','Distribution Design / SynerGEE Administrator','Mandatory form input. Source declares Metric globally but gives no field-level unit annotation. No conversion assumed. [EC, MDB]')
add(M,cat,'Phase-to-neutral spacing and source-unit interpretation','Confirm the spacing used for neutral/phase construction and its unit interpretation in the selected configuration.','Positive numeric centimetres in this form','Reference raw PhaseToNeutralSpacing_MUL=91.4','Distribution Design / SynerGEE Administrator','Mandatory form input; construction applicability and units need confirmation. [EC, MDB]')
add(M,cat,'Average conductor height above ground','Provide the design height used by the line model; do not substitute a pole length without an approved interpretation.','Positive numeric metres; form maximum 200 m','Reference AveHeightAboveGround_MUL=9.1 under Metric convention','Distribution Design / Survey Department','Mandatory form input. Reference model height is available; surveyed pole height is a different quantity. [EC, MDB]')
add(M,cat,'Survey pole-height unit confirmation','Confirm how original handwritten heights and older records are interpreted, so height conversions are consistent.','ft or m; current new PDF entries are stored in ft','Current application entry policy: feet; MDB model height does not prove paper-form units','Survey Department / Data Verification','Mandatory form choice. Confirm legacy/source units separately; retain original observations. [EC, PDF, UI]')
add(M,cat,'Transformer supply conductor library ID','Select the approved supply conductor model and settle its exact identity in the installed library.','Exact conductor ID in approved template reference inventory','Supply R/B: DOG; Y: one leading space plus DOG','Distribution Design / Library Custodian','Mandatory form selection. Resolve literal aliases rather than silently trimming source IDs. [EC, MDB]')
add(M,cat,'Transformer secondary-link conductor library ID','Select the installed conductor for the modeled secondary link, separately from distribution span materials.','Exact conductor ID in approved template reference inventory','Link R/B: ANT; Y: one leading space plus ANT','Distribution Design / Library Custodian','Mandatory form selection. This family choice does not resolve the blank link neutral. [EC, MDB]')
add(M,cat,'Surveyed kVA capacity to approved transformer type','Provide a type selection for every capacity present in the current survey; confirm the type represents the actual equipment.','JSON object: positive kVA capacity keys mapped to exact library IDs','Candidate labels only: {"50":"50 KVA","100":"100 KVA","200":"200 KVA"}','Transformer Engineering / Library Custodian','Mandatory mapping. Label-derived candidates need library confirmation; add any additional surveyed capacities through reviewed models. [EC, EPB]')
add(M,cat,'Transformer impedance source mode','Choose whether SynerGEE uses the approved library model or explicit instance impedance values.','UseInstanceImpedance integer: 0 for library, 1 for instance values','All nine transformer instances: UseInstanceImpedance=0','Transformer Engineering / System Planning','Mandatory explicit mode. Recorded PercentImpedance=0 / PercentResistance=0 are not physical zero-impedance evidence. [EC, EPB, MDB]')

cat='D. Survey interpretation and load-method decisions'
add(M,cat,'Two-digit survey-year interpretation window','Define how DDMMYY dates in complete waypoint IDs resolve to four-digit years.','Integer starting year; form range 1800-9900','No source policy. A start of 2000 would interpret 00-99 as 2000-2099','Survey Department / Data Verification','Mandatory form choice. This is an explanatory policy example, not an approved value; model years 2015-2025 do not establish it. [EC]')
add(M,cat,'Approved load-demand method','Choose measured/verified per-phase demand or a centrally approved category-rate estimation method.','manual or category_rates','No approved method recovered; 341 of 350 positive phase records are near 3 kVA/customer','System Planning / Load Research / Commercial','Mandatory method decision. Nine phase records differ; every positive-kVA phase has zero kW/kvar in references. [EC, MDB]')
add(M,cat,'Blank consumer-cell interpretation for final generation','Confirm whether a blank means unresolved information or an explicitly approved zero under the selected final-generation method.','Boolean blank_consumers_zero: false or true, with review basis','PDFs contain blanks; final-generation approval is not recorded in MDBs','Commercial / Data Verification / System Planning','Mandatory explicit policy. Independent Data Entry MDB zero-filling does not approve this final-model policy. [EC, NV]')
add(M,cat,'Demand methodology and allocation approval reference','Document the demand basis and allocation rule so section loads are reproducible and reviewed.','Text evidence, form maximum 4,000 characters; authorized review','References use fractional equal customer equivalents; app category method balances whole customers R/Y/B','System Planning / Load Research','Mandatory. Counts alone are not demand; source fractional allocation must not be copied as an approved integer allocation. [EC, NV]')

cat='E. Current network source and transformer connection mapping'
add(M,cat,'Approved source-node and terminal mapping','Specify current feeder/transformer connection aliases and bind physical source nodes to verified current survey coordinates.','mapping.networks[code].source_nodes list; unique aliases and valid waypoint links','References show feeder, HV and LV model nodes; no current-project binding approval','GIS / Distribution Planning / Survey Verification','Mandatory full model per transformer. GPX locates points; it does not establish the electrical source or synthetic terminal geometry. [EPB, NV]')
add(M,cat,'Approved source sections and explicit lengths','Define the source-to-transformer and secondary-link edges, phases, conductor IDs and modeling lengths.','source_sections list; valid from/to aliases; SectionLength_MUL in metres, nonnegative','Reference supply/link lengths: 1 m with one-unit node offsets','Distribution Planning / Network Studies','Mandatory full model. Historical one-metre links are modeling examples, not surveyed current lengths. [EPB]')
add(M,cat,'Feeder-source alias selection','Choose which source node is the feeder origin for connectivity checks and feeder creation.','feeder_node: exact alias from current source_nodes','Historical source alias/name varies by reference feeder','Distribution Planning / GIS','Mandatory per-transformer source mapping. Final database node IDs are generated by the application, not supplied manually. [EPB]')
add(M,cat,'Primary transformer section selection','Identify the approved source section on which the transformer instance must be attached.','transformer_section: exact key from source_sections','Reference transformer is attached to its first supply section','Transformer Engineering / Distribution Planning','Mandatory. Must resolve to an approved current section; do not copy historical section IDs. [EPB]')
add(M,cat,'Source-section phase and conductor schedule','Provide the exact R/Y/B/N positions on each modeled source/link edge, including absent phases.','SectionPhases fixed slots; e.g. RYB, RYBN, R BN; separate conductor IDs','Supply: RYB; secondary link: RYBN in references','Distribution Design / Network Verification','Mandatory for full source-section validation. An active N requires an actual approved neutral ID. [EPB]')
add(M,cat,'Current substation identifier in feeder mapping','Confirm the current substation identity used by the source-feeder mapping; historical names are not current identifiers.','Nonblank SubstationId string within canonical MDB field size','Historical example: 132 KVA K.Wala; not a current HAZECO assignment','Operations / Asset Register / GIS','Mandatory nonblank identifier. PDF headers help identify assets; official mapping requires verification. [EPB, PDF]')
add(M,cat,'Reviewed mapping version and current-network wiring','Review reusable table values and complete the per-transformer wiring in the existing supported mapping contract.','synergee-reviewed-v1 or v2; explicit supported table dictionaries; current networks object','133 common technical observations; no approved current-network source wiring','Network Studies / SynerGEE Administrator / Application Admin','Mandatory full mode. v2 is required when exporting supported meter/PV records. Approval metadata is recorded by the application. [EC, EPB, SM]')

cat='F. Conditional resolution of survey and library ambiguities'
add(C,cat,'Exact conductor IDs for unmatched PDF materials','Resolve a printed or handwritten material to the installed conductor model only when that material is actually used.','Per-material exact ID crosswalk and technical library definition','PDF legend includes PVC variants and ABC 50/95 mm²; nine-reference IDs do not resolve all of them','Distribution Design / Library Custodian','Conditional on material occurrence. Do not map PVC or ABC to ANT only because that reference exists. [PDF, LOOKUP, MDB]')
add(C,cat,'Whitespace and alias approval for conductor IDs','Decide whether literal leading-space references are aliases or distinct entries in the receiving library.','Reviewed mapping of exact strings; preserve spaces until confirmed','Observed: ANT / " ANT", DOG / " DOG", GNAT / " GNAT", WASP / " WASP"','Library Custodian / SynerGEE Administrator','Conditional where affected IDs are used; all four families have reported reference variants. [MDB]')
add(C,cat,'Secondary-link neutral model and continuity','Resolve the neutral conductor and connection when the link is declared to carry N.','Approved NeutralConductorId and confirmed phase/neutral schedule','Reference link SectionPhases=RYBN but NeutralConductorId is blank','Distribution Design / Operations','Conditional on N being declared. Full section validation rejects an active N without a reviewed conductor reference. [EPB, MDB]')
add(C,cat,'Historic first-S / KMZ root coordinates','Provide verified historic root coordinates where the first S reference is absent from the selected GPX.','Verified latitude/longitude and source evidence; current source association','PDFs contain historic transformer references separate from new GPS sequences','GIS / Asset Survey / Data Verification','Conditional on unmatched historic root. The first S KMZ reference cannot be replaced by a same-number unrelated GPX point. [NV, PDF]')
add(C,cat,'Ambiguous or repeated waypoint identity resolution','Confirm complete group/date/GPS identity and source selection where names or repeated observations do not uniquely identify a point.','Complete text identifier, selected GPX source and verified coordinate binding','GPX labels alone do not encode an approved electrical association','Survey / GIS / Data Verification','Conditional on ambiguity or missing matches; keep leading zeros in text IDs. [NV, GPX]')
add(C,cat,'Branch, intersection and normally-open connection resolution','Confirm which observed points are electrically connected when paper intersection flags or a branched layout are ambiguous.','Verified S/E edge schedule and radial source-connected topology','PDF Int flags exist; legacy Angle/Tap_Pole/End_Type equivalence is unconfirmed','Distribution Operations / Network Studies','Conditional on ambiguity/loops. Current exporter rejects cycles; it does not infer electrical connectivity from Int or proximity. [NV, EPB, PDF]')
add(C,cat,'Route geometry or measured span length','Supply route vertices or an approved measured length when straight endpoint distance is insufficient for the modeled section.','geometry coordinate list, or positive measured_length_m in metres','Source section lengths may match endpoint distances; GPX waypoints do not always define the route','GIS / Survey / Distribution Design','Conditional override. A measured length requires reason, provenance and verifier approval; no additional fixed length is assumed. [NV, EPB]')
add(C,cat,'Coordinate correction and approval','Confirm corrected coordinates and the reason when a recorded GPX point is wrong or missing.','Finite latitude/longitude within geographic bounds; reason and authorized approval','No universal correction can be derived from a reference model','GIS / Survey Verification','Conditional on correction. Preserve original coordinates; approval is required before the corrected point is used. [NV, EPB]')
add(C,cat,'Additional capacities / mixed construction models','Provide models and a mapping approach for surveyed capacities or constructions not represented by the consolidated library.','Exact new reviewed type/configuration IDs and per-network mapping where supported','Nine files only establish 50/100/200 KVA type labels and one configuration ID','Transformer Engineering / Distribution Design / Software Team','Conditional on occurrence. Central settings currently apply one configuration; heterogeneous construction may need explicit mapping review. [EC, EPB]')

cat='G. Category-rate demand inputs (only when category_rates is selected)'
categories=[('RS','1-phase residential'),('RL','3-phase residential'),('SC','1-phase commercial'),('LC','commercial LC; classification needs confirmation'),('SI','1-phase industrial'),('LI','3-phase industrial'),('PB','public buildings'),('AG','agriculture'),('ST','street lights')]
for code,meaning in categories:
    add(C,cat,f'{code} demand rate ({meaning})','Provide the approved per-customer apparent-demand rate used to convert the verified category count into estimated demand.','Numeric kVA/consumer, 0 to 1,000,000; supported rate input', 'No category-specific rate in MDBs; aggregate ratios include about 3, 3.8667, 4 and 5', 'Load Research / Commercial / System Planning',f'Conditional: category_rates mode requires a rate for every category, including {code}. Aggregate historical ratios are not an approved rate schedule. [EC]')
    add(C,cat,f'{code} lagging power factor','Provide the approved factor used to calculate kW and kvar from the category apparent-demand estimate.','Numeric factor greater than 0 and at most 1; lagging model in current automatic method','No usable value: reference positive kVA has zero kW and kvar','Load Research / Metering / System Planning',f'Conditional: category_rates requires PF for {code}. Signed measured kvar or another allocation method uses the verified-demand workflow. [EC, NV]')

cat='H. Verified phase demands (only when manual demand is selected)'
for quantity,unit,fmt in [('customers','customers','Nonnegative whole integer; total equals verified category count'),('kW','kW','Finite nonnegative numeric kW'),('kvar','kvar','Finite numeric kvar; signed values allowed with approval'),('kVA','kVA','Finite nonnegative numeric kVA')]:
    for phase in ['R','Y','B']:
        sample='Not established for the current project'
        if quantity=='customers': sample='References often use fractional equivalents; these do not satisfy the current integer allocation rule'
        if quantity in ['kW','kvar']: sample='References record 0 even where kVA is positive; not a measured-demand basis'
        add(C,cat,f'{phase}-phase {quantity} by section / category','Provide the verified connected-phase demand schedule. Link each value to its current section, consumer category and measurement/estimation evidence.',fmt,sample,'Metering / Load Research / System Planning','Conditional: manual demand, positive consumer counts and the indicated active phase. Inactive phases cannot carry nonzero loads. Check kW/kvar/kVA consistency. [NV, EPB]')

cat='I. Transformer model, connection and impedance options'
add(C,cat,'Nominal-voltage mode interpretation','Confirm the receiving SynerGEE meaning of the nominal-voltage mode and ensure its value is consistent with the LT form field and library.','Supported NomKvMode code; verified voltage basis','Reference: NomKvMode=C, SpecNomKv=4.16','Transformer Engineering / SynerGEE Administrator','Conditional model semantic review. Do not label C as a particular calculation mode without vendor/library confirmation. [MDB, EC]')
add(C,cat,'Instance transformer percent impedance','Supply tested/approved impedance when choosing explicit instance impedance instead of the library.','PercentImpedance: positive numeric percent; declare rating/base','Reference value 0 with UseInstanceImpedance=0 is not a usable instance value','Transformer Testing / Transformer Engineering','Conditional mandatory when UseInstanceImpedance=1. Otherwise verified library impedance applies. [EC, EPB]')
add(C,cat,'Instance transformer percent resistance','Supply resistance on the same declared transformer base as the instance impedance.','PercentResistance: nonnegative numeric percent; same base as impedance','Reference value 0 with library mode enabled; no tested resistance recovered','Transformer Testing / Transformer Engineering','Conditional mandatory when UseInstanceImpedance=1; do not infer resistance from transformer make or capacity alone. [EC, EPB]')
for side,field in [('High','HighSideConnectionCode'),('Low','LowSideConnectionCode')]:
    add(C,cat,f'{side}-side transformer winding connection','Confirm the winding connection used by the selected transformer model and its relationship to the actual circuit.','Exact supported '+field+' code','Both references use YG on high and low sides','Transformer Engineering / Asset Records','Conditional on selected transformer representation. Recorded codes are available but not current-project nameplate evidence; not a separate universal form gate. [MDB]')
add(C,cat,'Transformer side orientation on the source section','Confirm which section end represents each winding side so voltage transformation follows the intended topology.','HighSideNearFromNode / NearFromNode supported flags','Reference: HighSideNearFromNode=1; NearFromNode=0','Network Studies / Transformer Engineering','Conditional model confirmation. Do not copy orientation onto reversed or different current source wiring. [MDB, EPB]')
for side in ['High','Low']:
    add(C,cat,f'{side}-side grounding resistance and reactance','Provide the actual grounding model if grounding/sequence studies or the selected transformer connection require explicit values.','Resistance/reactance in the installed model native units; basis confirmed','Recorded '+side+'SideGroundingResistance=0 and Reactance=0','Protection / Earthing Design / Transformer Engineering','Conditional on grounding study/model. Zero reference fields are not proof of measured earth resistance. Not an unconditional export gate. [MDB]')
add(C,cat,'Transformer tap setting','Confirm the transformer tap represented by the model rather than copying a historic instance.','Supported TapSetting numeric value; meaning/basis from receiving library','Reference TapSetting=1','Distribution Operations / Transformer Engineering','Conditional on transformer/tap representation. Not a substitute for nameplate tap position or approved voltage regulation settings. [MDB]')
add(C,cat,'LC category interpretation and connection policy','Confirm the LC tariff/classification and how its demand is represented; retain the recorded category until reviewed.','Written category definition and approved rate or measured-demand mapping','Application label: Commercial (LC; confirm classification)','Commercial / Load Research','Conditional when LC data are modeled. No automatic reclassification or inferred phase count from the label. [LOOKUP, EC]')

cat='J. PV and annual generator modeling (only for included PV)'
add(C,cat,'PV inclusion or approved exclusion decision','Decide whether each positive PV record is represented by the supported generator mapping or covered by an explicit engineering-approved exclusion.','v2 generator mapping, or pv_exclusion reason with authorized review','One Kot Madina reference contains a generator; PDF PV fields do not establish a model policy','Distributed Generation / System Planning','Conditional on positive PV capacity. Omitting it without an approved exclusion fails full validation. [NV, SM]')
add(C,cat,'PV-to-current-section association','Identify the actual section and PV observation belonging to each generator; resolve multiple PV records on one section.','pv_record_id and current section_id; one supported generator per section','Reference IDs belong to historical networks; current association not provided','DG / GIS / Survey Verification','Conditional on included PV. Current writer rejects duplicate generator mappings and does not arbitrarily aggregate several installations. [SM]')
add(C,cat,'Generator output percentage','Provide the generator output percentage under the approved operating scenario.','DGenOutputPct: finite numeric 0-100 percent','Component reference evidence includes DGenOutputPct=100','DG / System Planning','Conditional mandatory for included full-mode generator; source component settings are not universal defaults. [SM, MDB]')
add(C,cat,'Generator voltage setpoint and unit basis','Confirm the generator setpoint and the voltage basis expected by the selected SynerGEE model.','DGenVoltSet: positive numeric in supported native model units; basis declared','Component reference evidence includes DGenVoltSet=120','DG / Voltage Control / SynerGEE Administrator','Conditional mandatory for included full-mode generator. Do not interpret 120 as kV or LT voltage without confirming units. [SM, MDB]')
add(C,cat,'Generator study-year numbering and base-year meaning','Define modeled year indices and their actual calendar/scenario meaning; include the required base year.','Unique nonnegative YearNumber integers; base index 0 required','Historical SAI model years 2015-2025; not the current study schedule','System Planning / DG','Conditional on annual PV modeling. Current mapping requires a base-year (0) record but does not infer current calendar labels. [SM]')
add(C,cat,'Annual generator capacity factor','Provide the scenario/year capacity factor used for each generator annual record.','Finite CapacityFactor from 0 to 1, for each modeled year','Reference component evidence available; current annual scenario not approved','DG / Renewable Planning','Conditional mandatory for each full-mode generator-year record. Do not derive from installed kW alone. [SM]')
for q in ['kW','kvar']:
    for phase in ['R','Y','B']:
        add(C,cat,f'Generator {phase}-phase {q} for every modeled year','Provide the generator output for the indicated connected phase, with the scenario and year recorded.','Finite nonnegative kW' if q=='kW' else 'Finite numeric kvar; signed values allowed','Historical generator outputs are instance/year-specific, not reusable current values','DG / Metering / Network Studies','Conditional mandatory for this active generator phase. Inactive phases must be NULL or zero; no automatic split of installed PV capacity. [SM]')
add(C,cat,'Meter-point section association','Choose where a meter point is attached if meter records are required in the intended study.','Exactly one source_section or survey_section_id per meter; one meter per section','All nine references have a meter row with only SectionId populated','Metering / GIS / Network Studies','Conditional on adding meters. Blank readings in references are not a requirement to invent measurements. [SM, MDB]')

cat='K. Optional supply, voltage-control and study settings'
add(O,cat,'Projection WKT or alternate projection reference','Provide additional CRS definition text only if required by the receiving installation or document standard.','Optional projection_wkt text, form maximum 255 characters','Reference ProjectionWKT is an empty string','GIS / SynerGEE Administrator','Optional. The form accepts blank; do not truncate an external WKT to fit. EPSG/name confirmation remains mandatory. [EC, MDB]')
add(O,cat,'Operating feeder bus voltage','Specify the operating source voltage for a study when it differs from nominal voltage.','BusVoltageLevel in supported SynerGEE voltage basis','Reference BusVoltageLevel=11.37; nominal feeder voltage=11','System Operations / System Planning','Optional study value, not the form nominal-voltage field. Confirm units and scenario before reuse. [MDB]')
